def _import(name):
    """从本 skill 的 src 目录导入真实模块; 失败返回 (None, 异常)。"""
    src = str(SRC_DIR)                                                            # 包根即 skill 根: 注入它才能 import 到本 skill 的模块
    if os.path.isdir(src) and src not in sys.path:  # 幂等: 重复插入会让 import 走两条路径
        sys.path.insert(0, src)                                                                     # 挂到最前: 否则可能先解析到别的同名包
