# 字段契约权威元数据: 每个字段对应的文件名 / type / unit (与 spec 同源)
FIELDS_FILES = {'input': {'sql': {'file': 'sql.contract.yaml', 'type': 'string', 'unit': 'dimensionless'}, 'token': {'file': 'token.contract.yaml', 'type': 'string', 'unit': 'credential'}}, 'output': {'data': {'file': 'data.contract.yaml', 'type': 'object', 'unit': 'mixed'}, 'status': {'file': 'status.contract.yaml', 'type': 'string', 'unit': 'dimensionless'}}}  # 四个字段契约的权威元数据: 文件名与类型单位都在这里, 契约文件按它核对


def test_gen_field_contracts_exist_and_match_spec():
    """四个字段契约必须齐备, 且 field/type/unit/direction 与 spec 逐项一致。

    结尾的 ``checked`` 计数断言是防呆: 若 FIELDS_FILES 被悄悄改短, 循环
    「全绿但什么都没查」的情况就不会发生。
    """
    if not CONTRACTS_DIR.is_dir():                                                               # 契约尚未物化时跳过: 那不是回归, 是还没生成
        pytest.skip("contracts/ 尚未物化")
    checked = 0                                                                       # 计数防呆: FIELDS_FILES 被改短时循环会全绿而什么都没查
    for direction, fields in FIELDS_FILES.items():  # 双层遍历: (输入|输出) x 字段
        for fname, fmeta in fields.items():                                                  # 逐个字段逐项比对: 少比一项就等于给那一项开了免检通道
            p = CONTRACTS_DIR / "fields" / fmeta["file"]  # 文件名取自权威元数据, 不在这里拼字面量
            assert p.is_file(), f"缺少字段契约: {p}"  # 缺文件即红: 磁盘消失后契约不能继续显示全绿
            data = yaml.safe_load(p.read_text(encoding="utf-8"))
            assert data["field"] == fname  # 四项逐字比对, 任一漂移都是跨 skill 契约破坏
            assert data["type"] == fmeta["type"]
            assert data["unit"] == fmeta["unit"]
            assert data["direction"] == direction  # direction 错 = 消费方在错的一侧找字段
            checked += 1                                                                        # 每核一个字段加一: 这个计数是下面那条对账的依据
    assert checked == sum(len(v) for v in FIELDS_FILES.values())  # 计数对账: 防 FIELDS_FILES 被改短
